        "key": "Recommendations",
        "label": "التوصيات",
        "value": "١. تجنب التحديق الطويل الذي قد يُفهم استفزازاً للطالب.\n٢. الجمع بين تدوين السلوكيات السلبية والإيجابية في السجل نفسه.\n٣. استخدام السجل في تحليل السلوك لا في التهديد به."
