        "value": "١. الصدق في العبارة الختامية حتى لا يشعر الطلاب بالمجاملة.\n٢. تنويع صيغ الختام حتى لا تتحول إلى عبارة محفوظة مكررة.\n٣. تأجيل معالجة الأخطاء إلى بداية الحصة التالية لا ختامها."
