        "value": "يُتاح في هذه الاستراتيجية للطالب المنضبط أو المتميز أن يشرح جزءاً من الدرس أو يدير نشاطاً صفياً، فيكون ذلك تعزيزاً لمكانته وثقته بنفسه أمام زملائه داخل الفصل ودافعاً لاستمرار انضباطه لاحقاً."
